class Team:
    def __init__(self, name, wins, losses, opponents):
        self.name = name
        self.wins = wins
        self.losses = losses
        self.opponents = opponents

    def calculate_sos(self):
        sos = 0
        for opponent in self.opponents:
            sos += opponent.sos
        return sos / len(self.opponents)

    def calculate_sov(self):
        sov = 0
        for win in self.wins:
            sov += win.sos
        return sov / len(self.wins)

    def calculate_sol(self):
        sol = 0
        for loss in self.losses:
            sol += loss.sos
        return sol / len(self.losses)

