Firstly, you need to create a resolver for your search query. This resolver will handle the logic of searching for available vans and their variations.

```typescript
// van.resolver.ts
import { Resolver, Query, Args, Field, Ctx } from '@nestjs/graphql';
import { Prisma } from '@prisma/client';
import { Context } from 'src/context';
import { Van } from 'src/van/entities/van.entity';
import { VanVariation } from 'src/vanVariation/entities/vanVariation.entity';
import { Booking } from 'src/booking/entities/booking.entity';

@Resolver()
export class VanResolver {
  @Query('searchVans')
  async searchVans(
    @Args('fromDate') fromDate: Date,
    @Args('toDate') toDate: Date,
    @Ctx() context: Context,
  ): Promise<VanVariation[]> {
    const prisma = context.prisma;

    // Find all bookings that overlap with the given date range
    const bookings = await prisma.booking.findMany({
      where: {
        AND: [
          {
            startDate: {
              lte: toDate,
            },
          },
          {
            endDate: {
              gte: fromDate,
            },
          },
        ],
      },
    });

    // Find all vans that are not booked during the given date range
    const availableVans = await prisma.van.findMany({
      where: {
        id: {
          notIn: bookings.map((booking) => booking.vanId),
        },
      },
    });

    // Find all van variations for the available vans
    const vanVariations = await prisma.vanVariation.findMany({
      where: {
        van: {
          id: {
            in: availableVans.map((van) => van.id),
          },
        },
      },
    });

    // Remove duplicates of van variations
    const uniqueVanVariations = vanVariations.reduce((acc, current) => {
      const existing = acc.find((vanVariation) => vanVariation.id === current.id);
      if (!existing) {
        acc.push(current);
      }
      return acc;
    }, []);

    return uniqueVanVariations;
  }
}
```

Then, you need to create a GraphQL query in your schema to call this resolver.

```typescript
// van.schema.ts
import { Field, InputType, Int, Float } from '@nestjs/graphql';
import { VanVariation } from 'src/vanVariation/entities/vanVariation.entity';

@InputType()
export class SearchVansInput {
  @Field(() => Float)
  fromDate: Date;

  @Field(() => Float)
  toDate: Date;
}

@ObjectType()
export class SearchVansOutput {
  @Field(() => [VanVariation])
  vanVariations: VanVariation[];
}

@Query(() => SearchVansOutput)
async searchVans(
  @Args('input') input: SearchVansInput,
): Promise<SearchVansOutput> {
  return await this.vanResolver.searchVans(input.fromDate, input.toDate);
}
```

Finally, you can call this query in your GraphQL schema.

```typescript
// app.module.ts
import { Module } from '@nestjs/common';
import { GraphQLModule } from '@nestjs/graphql';
import { PrismaModule } from '@prisma/client';
import { VanModule } from './van/van.module';
import { VanResolver } from './van/van.resolver';

@Module({
  imports: [
    GraphQLModule.forRoot({
      autoSchemaFile: true,
      resolvers: [VanResolver],
    }),
    PrismaModule.forRoot(),
    VanModule,
  ],
})
export class AppModule {}
```

